import{_ as a,o,c as s,a5 as i}from"./chunks/framework.BwlBv862.js";const f=JSON.parse('{"title":"Usar TikTools","description":"","frontmatter":{"title":"Usar TikTools","docId":"user.overview","translationKey":"user.overview","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"72ce37218d4f3341fccd306bd0b1b4039ec6e1fd3dcfeb16f9096f43576c861d","translationRevision":"70f169442349567495d1af0de37ae3a35dbdc462cfbd884fdebe39e9d1ce5ff0","order":0},"headers":[],"relativePath":"es/user/index.md","filePath":"es/user/index.md","lastUpdated":1794611623000}'),n={name:"es/user/index.md"};function t(r,e,l,c,d,u){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="use-tiktools" tabindex="-1">Usar TikTools <a class="header-anchor" href="#use-tiktools" aria-label="Permalink to &quot;Usar TikTools {#use-tiktools}&quot;">​</a></h1><p>TikTools conecta un escritorio Windows o Linux a un TikTok LIVE, muestra sus eventos, conserva puntos de espectadores y ejecuta reglas en tu equipo. La interfaz de escritorio y el host opcional sin interfaz comparten el mismo núcleo Rust. La cuenta Cloud es independiente de la conexión con TikTok.</p><h2 id="choose-your-first-task" tabindex="-1">Elige tu primera tarea <a class="header-anchor" href="#choose-your-first-task" aria-label="Permalink to &quot;Elige tu primera tarea {#choose-your-first-task}&quot;">​</a></h2><ol><li>Revisa los <a href="./requirements.html">requisitos</a> e <a href="./installation.html">instala un binario publicado</a>. Para usar el escritorio no necesitas Rust, Cargo ni Bun.</li><li><a href="./first-live.html">Conecta con un LIVE</a>, empezando sin cookie de TikTok cuando la sala permita acceso de invitado.</li><li>Usa <strong>Live feed</strong> para inspeccionar eventos. <strong>Points</strong> conserva totales por espectador; <strong>Analytics</strong> muestra estadísticas. <strong>Automations</strong> relaciona disparadores con acciones configuradas.</li><li>Instala integraciones opcionales desde <strong>Plugins</strong>. Los paquetes externos se distribuyen por separado de la aplicación.</li><li>Usa <strong>Overlays</strong> para preparar una Browser Source de OBS. La entrega de widgets en vivo requiere la integración de gateway.</li></ol><h2 id="available-and-experimental-features" tabindex="-1">Funciones disponibles y experimentales <a class="header-anchor" href="#available-and-experimental-features" aria-label="Permalink to &quot;Funciones disponibles y experimentales {#available-and-experimental-features}&quot;">​</a></h2><p>La navegación principal muestra Live feed, Points, Analytics, Connections, Automations, Plugins, Overlays y Settings. Rankings y competencias tienen un motor nativo y una ruta directa, pero su página de gestión sigue oculta en la navegación normal. Los diseños antiguos pueden describir funciones que todavía no están publicadas.</p><p>Los cambios de plugins en Cloud y las Variables revisadas usan controles explícitos por sección. Automations compara actualmente contra una referencia local; ese botón no publica perfiles en Cloud. Los transportes de colaboración y algunos procesos de instalación siguen siendo experimentales. Un control deshabilitado suele indicar una capacidad ausente del host o un requisito pendiente.</p><h2 id="when-something-fails" tabindex="-1">Si algo falla <a class="header-anchor" href="#when-something-fails" aria-label="Permalink to &quot;Si algo falla {#when-something-fails}&quot;">​</a></h2><p>Abre <strong>Diagnostics</strong>, conserva el origen del error y su identificador de solicitud, y anota la versión instalada. Evita incluir cookies, tokens de invitación o valores privados de variables. Empieza por la recuperación de cada guía y después consulta soporte. La demo interactiva usa datos ficticios y no demuestra que funcionen tu cuenta TikTok, OBS o tu red.</p><p>Para trabajar con el código fuente, utiliza la <a href="./../developer/">documentación de desarrollo</a>.</p>',10)])])}const m=a(n,[["render",t]]);export{f as __pageData,m as default};
